const config = {
  "previewFeatures": [],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "postgresql",
  "inlineSchema": "// =============================================================================\n// SERVITEX — Schema de Base de Datos (Prisma ORM)\n// Versión: 2.0.0\n// Entregable 2: Módulo Formulario + Procedimientos Químicos (Secciones 2 y 3)\n// Tipado Estricto: Todos los valores físicos, químicos y monetarios son Float.\n// =============================================================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// =============================================================================\n// ENUMERACIONES\n// =============================================================================\n\n/// Tipos de cliente reconocidos por el sistema comercial de SERVITEX.\nenum TipoCliente {\n  EMPRESA\n  PERSONA_NATURAL\n  TALLER_EXTERNO\n  DISTRIBUIDOR\n}\n\n/// Composición de fibra del artículo.\n/// Determina la ruta química automática que el sistema ejecutará (Sección 3.2 y 3.3).\nenum ComposicionFibra {\n  ALGODON // Ruta: 5 baños de teñido + 4 de preblanqueo = 9 total\n  NYLON // Ruta: 4 baños (ácido directo en baño 1, sin neutralizado separado)\n  POLIESTER // Ruta: 4 baños (ácido directo en baño 1, sin neutralizado separado)\n  MULTIFIBRA_ALGODON_NYLON // Ruta: 7 baños (neutralizado del algodón eliminado)\n  MULTIFIBRA_ALGODON_POLIESTER // Ruta: 7 baños (neutralizado del algodón eliminado)\n  MULTIFIBRA_NYLON_POLIESTER // Ruta: 7 baños (Poliéster primero, luego Nylon)\n}\n\n/// Estado del ciclo de vida de una Orden de Compra.\nenum EstadoOrden {\n  PENDIENTE // Registrada, sin iniciar producción\n  EN_PROCESO // Al menos un lote está en formulario técnico\n  COMPLETADA // Todos los lotes han sido procesados\n  ANULADA // Cancelada por el cliente o el taller\n}\n\n// =============================================================================\n// MODELO: Cliente\n// Catálogo maestro de clientes. Reutilizable en múltiples órdenes de compra.\n// =============================================================================\nmodel Cliente {\n  id          Int         @id @default(autoincrement())\n  nombre      String      @db.VarChar(200)\n  tipoCliente TipoCliente\n  ruc         String?     @unique @db.VarChar(11)\n  telefono    String?     @db.VarChar(15)\n  correo      String?     @db.VarChar(150)\n  direccion   String?     @db.VarChar(300)\n  createdAt   DateTime    @default(now())\n  updatedAt   DateTime    @updatedAt\n\n  ordenes OrdenCompra[]\n\n  @@unique([nombre, tipoCliente], name: \"nombre_tipoCliente\")\n  @@map(\"clientes\")\n}\n\n// =============================================================================\n// MODELO: OrdenCompra (CABECERA)\n// Datos fijos que el usuario registra una sola vez al inicio.\n// Regla: Una OrdenCompra tiene MUCHOS DetalleOrden (teñidos individuales).\n// =============================================================================\nmodel OrdenCompra {\n  id            Int         @id @default(autoincrement())\n  numeroOC      String      @unique @db.VarChar(50)\n  clienteId     Int\n  cliente       Cliente     @relation(fields: [clienteId], references: [id])\n  estado        EstadoOrden @default(PENDIENTE)\n  observaciones String?     @db.Text\n  createdAt     DateTime    @default(now())\n  updatedAt     DateTime    @updatedAt\n\n  detalles DetalleOrden[]\n\n  @@map(\"ordenes_compra\")\n}\n\n// =============================================================================\n// MODELO: DetalleOrden (FILAS DINÁMICAS — Teñido Individual)\n// Cada fila es un lote de teñido independiente asociado a una OC.\n// =============================================================================\nmodel DetalleOrden {\n  id                  Int         @id @default(autoincrement())\n  ordenCompraId       Int\n  ordenCompra         OrdenCompra @relation(fields: [ordenCompraId], references: [id], onDelete: Cascade)\n  cantidad            Float\n  unidadMedida        String      @default(\"Metros\") @db.VarChar(20)\n  descripcionArticulo String      @db.VarChar(300)\n  colorSolicitado     String      @db.VarChar(150)\n  precioPorMetro      Float\n  total               Float\n  createdAt           DateTime    @default(now())\n  updatedAt           DateTime    @updatedAt\n\n  recetaTecnica RecetaTecnica?\n\n  @@map(\"detalles_orden\")\n}\n\n// =============================================================================\n// MODELO: RecetaTecnica (FORMULARIO TÉCNICO — Secciones 2 y 3)\n// Expandido en Entregable 2 con todos los campos de laboratorio.\n// Vinculada 1-a-1 con DetalleOrden y 1-N con ColoranteFormula.\n//\n// TIPADO ESTRICTO (obligatorio por documento SERVITEX):\n//   pesoRealKg     → Float (admite decimales de balanza: 1.75 kg)\n//   relacionBano   → Float (parte numérica de 1:X, ej. 40.0)\n//   litrosAgua     → Float (calculado: pesoRealKg × relacionBano)\n//   nivelIntensidad→ Float (nivel 1.0–4.0 según suma de %% de colorantes)\n// =============================================================================\nmodel RecetaTecnica {\n  id Int @id @default(autoincrement())\n\n  /// Relación 1-1: cada RecetaTecnica pertenece a un único DetalleOrden (lote).\n  detalleOrdenId Int          @unique\n  detalleOrden   DetalleOrden @relation(fields: [detalleOrdenId], references: [id], onDelete: Cascade)\n\n  // ------------------------------------------------------------------\n  // SECCIÓN 2.1 — DATOS FÍSICOS DE ENTRADA\n  // ------------------------------------------------------------------\n\n  /// Peso real del artículo medido en balanza de planta. Float obligatorio.\n  /// Es la base de todos los cálculos de gramos de productos químicos.\n  /// Ejemplo: 2.0 (kg)\n  pesoRealKg Float\n\n  /// Tipo de artículo textil que ingresa al proceso.\n  /// Ejemplo: \"Avío\", \"Prenda\", \"Cierre\", \"Tela cruda\", \"Hilo\".\n  articulo String @db.VarChar(150)\n\n  /// Composición de fibra. Determina la ruta química automática del sistema.\n  /// Ver enum ComposicionFibra para las rutas disponibles (Sección 3.2 / 3.3).\n  composicionFibra ComposicionFibra\n\n  /// Relación de Baño: se almacena solo la parte numérica de la relación 1:X.\n  /// Ejemplo: para una relación 1:40 se almacena 40.0\n  /// Regla de cálculo: litrosAgua = pesoRealKg × relacionBano\n  /// El mismo volumen se aplica a TODOS los baños del proceso.\n  relacionBano Float\n\n  /// Litros de agua por baño, calculados automáticamente por el backend al guardar.\n  /// Fórmula: pesoRealKg × relacionBano\n  /// Ejemplo: 2 kg × 40 = 80.0 litros por cada uso de agua.\n  litrosAgua Float\n\n  // ------------------------------------------------------------------\n  // SECCIÓN 2.2 — FÓRMULA DEL COLOR\n  // Relación normalizada: una receta tiene MUCHOS ColoranteFormula.\n  // Reemplaza el campo formulaColorJson del Entregable 1.\n  // ------------------------------------------------------------------\n\n  /// Nombre descriptivo del color objetivo a producir.\n  /// Ejemplo: \"Keeneland Khaki\", \"Navy Blue\", \"Coral Reef\".\n  descripcionColor String @db.VarChar(200)\n\n  /// Nivel de intensidad calculado automáticamente por el sistema (Sección 3.4).\n  /// Se determina sumando los porcentajes de todos los colorantes de la fórmula:\n  ///   1.0 = Pasteles       (suma ≤ 0.01%)\n  ///   2.0 = Claros         (suma > 0.01% y ≤ 0.1%)\n  ///   3.0 = Intermedios    (suma > 0.1% y ≤ 1.0%)\n  ///   4.0 = Intensos       (suma > 1.0%)\n  /// Float obligatorio — permite representar el nivel como valor numérico exacto.\n  nivelIntensidad Float\n\n  // ------------------------------------------------------------------\n  // SECCIÓN 2.3 — OBSERVACIONES TÉCNICAS\n  // ------------------------------------------------------------------\n\n  /// Notas libres del dueño: incidencias o excepciones del cliente.\n  /// Ejemplo: \"cliente solicita omitir suavizado\", \"repetir enjuague 2 veces\".\n  observacionesTecnicas String? @db.Text\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  /// Relación 1-N: una receta tiene muchos colorantes con sus porcentajes.\n  colorantes ColoranteFormula[]\n\n  @@map(\"recetas_tecnicas\")\n}\n\n// =============================================================================\n// MODELO: ColoranteFormula (FÓRMULA DEL COLOR — Sección 2.2)\n// Cada fila representa un colorante individual con su porcentaje en la fórmula.\n// Reemplaza el campo formulaColorJson (JSON plano) por una relación normalizada.\n//\n// Regla de UI: la interfaz filtra los colorantes disponibles según la\n// composición de fibra de la RecetaTecnica antes de mostrarlos al usuario.\n//\n// TIPADO ESTRICTO:\n//   porcentaje → Float obligatorio (ej: 0.5 para 0.5% sobre el peso del artículo)\n// =============================================================================\nmodel ColoranteFormula {\n  id Int @id @default(autoincrement())\n\n  /// FK a la Receta Técnica a la que pertenece este colorante.\n  recetaTecnicaId Int\n  recetaTecnica   RecetaTecnica @relation(fields: [recetaTecnicaId], references: [id], onDelete: Cascade)\n\n  /// Nombre del colorante compatible con la fibra seleccionada.\n  /// Ejemplo: \"Dianix Blue AC-E\", \"Ramazol Yellow\", \"Reactivo Rojo 3BS\".\n  nombreColorante String @db.VarChar(200)\n\n  /// Porcentaje de concentración del colorante. Float obligatorio.\n  /// Ejemplo: 0.5 representa el 0.5% sobre el peso del artículo.\n  /// La SUMA de todos los porcentajes de la fórmula determina el nivelIntensidad.\n  porcentaje Float\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"colorantes_formula\")\n}\n"
}

